const reactScenarios = {
    "React Fundamentals": {
        hints: ["Start from props and state as inputs to a pure render description.", "Trace what triggers a render and ensure the component does not modify the DOM or input data directly."],
        items: [
            ["Easy", "Render a conditional empty state", "Build a React component that receives an array of saved jobs and displays either one list item per job or a useful empty message. Keep the rendering declarative and include a stable key derived from each job's ID.", "Two jobs render two titles; an empty array renders 'No saved jobs yet.'", "A missing savedJobs prop should be treated as an empty array without throwing.", "function SavedJobs({ savedJobs = [] }) { return savedJobs.length ? <ul>{savedJobs.map((job) => <li key={job.id}>{job.title}</li>)}</ul> : <p>No saved jobs yet.</p>; }"],
            ["Easy", "Keep a component render pure", "A status component receives status and returns the matching label. Refactor it so rendering does not mutate a module variable or log analytics; the same props must always produce the same UI description.", "status='complete' consistently renders 'Completed'.", "An unknown status returns a neutral 'Status unavailable' label.", "function StatusLabel({ status }) { const labels = { complete: 'Completed', active: 'In progress', pending: 'Not started' }; return <span>{labels[status] ?? 'Status unavailable'}</span>; }"],
            ["Medium", "Derive a visible job count", "Create a job results component that receives jobs and a keyword and displays matching jobs plus a result count. Derive the filtered list during render, match title and company case-insensitively, and do not duplicate the derived list in state.", "Query 'design' matches a design title or company and the count equals rendered rows.", "A whitespace-only query shows all jobs; no matches displays an honest empty state.", "function JobResults({ jobs, query }) { const term = query.trim().toLowerCase(); const visible = jobs.filter((job) => !term || [job.title, job.company].some((value) => value?.toLowerCase().includes(term))); return <section><p>{visible.length} results</p>{visible.length ? visible.map((job) => <article key={job.id}>{job.title} · {job.company}</article>) : <p>No jobs match this search.</p>}</section>; }"],
            ["Medium", "Prevent a mutated prop from corrupting the next render", "A component sorts its jobs prop in place before rendering. Fix the component so sorting is stable for equal dates and does not modify the parent-owned array.", "The displayed list is newest first while the original jobs array retains its order.", "Equal timestamps keep their original relative order.", "function NewestJobs({ jobs }) { const sorted = [...jobs].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)); return sorted.map((job) => <article key={job.id}>{job.title}</article>); }"],
            ["Hard", "Keep list row identity through filtering", "A task list uses array indexes as keys and each row has local expanded state. Reordering or filtering attaches expanded content to the wrong task. Refactor identity and explain why React keys are part of reconciliation rather than display text.", "Expanded state remains associated with the same task ID after sorting.", "Two tasks with identical titles remain distinct because their IDs differ.", "function TaskList({ tasks }) { return tasks.map((task) => <TaskRow key={task.id} task={task} />); }\nfunction TaskRow({ task }) { const [expanded, setExpanded] = React.useState(false); return <article><button onClick={() => setExpanded((value) => !value)}>{task.title}</button>{expanded && <p>{task.description}</p>}</article>; }"],
            ["Hard", "Separate server state from derived presentation", "A dashboard fetches job records, stores both the response and a second filteredJobs state array, and updates the two in different handlers. Refactor the state model so only source data and user query are state, then derive visible jobs and counts consistently.", "Changing the query updates rows and count in the same render without a second synchronization effect.", "An API refresh replaces source jobs and immediately recalculates the current query.", "function Results({ jobs, query }) { const visible = React.useMemo(() => { const term = query.trim().toLowerCase(); return jobs.filter((job) => !term || job.title.toLowerCase().includes(term)); }, [jobs, query]); return <><p>{visible.length} results</p>{visible.map((job) => <article key={job.id}>{job.title}</article>)}</>; }"],
        ]
    },
    Components: {
        hints: ["Give each component one clear responsibility and make data flow through explicit props.", "Keep semantic HTML and accessible naming in the reusable component contract, not only in one caller."],
        items: [
            ["Easy", "Compose a labeled metric card", "Create a reusable MetricCard that accepts label, value, and an optional description. Use a heading for the label and preserve numeric zero as a valid value instead of replacing it with a fallback.", "label='Open tasks', value=0 renders the label and 0.", "An omitted description adds no empty paragraph; a missing value displays an em dash.", "function MetricCard({ label, value, description }) { return <article><h3>{label}</h3><strong>{value ?? '—'}</strong>{description && <p>{description}</p>}</article>; }"],
            ["Easy", "Extract a reusable loading message", "Two pages show the same pending state. Extract a LoadingStatus component with a required message and status semantics so screen readers are informed while the page is waiting.", "Both parent pages render the same role=status message with different text.", "No loading message is rendered after the parent switches to success state.", "function LoadingStatus({ message }) { return <p role='status'>{message}</p>; }"],
            ["Medium", "Split a form from its field row", "A profile editor repeats label, input, and error markup for name and location. Create a reusable FormField component with id, label, value, onChange, and optional error props; associate the error with the control and keep field state in the parent.", "Both fields remain controlled by the profile editor and errors are announced for their own inputs.", "A field with no error has no dangling aria-describedby reference.", "function FormField({ id, label, value, onChange, error }) { return <div><label htmlFor={id}>{label}</label><input id={id} value={value} onChange={onChange} aria-invalid={Boolean(error)} aria-describedby={error ? `${id}-error` : undefined} />{error && <p id={`${id}-error`}>{error}</p>}</div>; }"],
            ["Medium", "Keep a reusable button's API narrow", "A shared action button receives arbitrary HTML props, custom styles, and a click callback; callers accidentally override its disabled state. Define an explicit variant, disabled, and onClick contract while forwarding safe native button attributes.", "A disabled save button cannot invoke onClick and retains type='button'.", "A caller-supplied type='submit' is supported only when explicitly passed as an allowed native prop.", "function ActionButton({ variant = 'primary', disabled = false, onClick, children, type = 'button', ...nativeProps }) { return <button {...nativeProps} type={type} data-variant={variant} disabled={disabled} onClick={disabled ? undefined : onClick}>{children}</button>; }"],
            ["Hard", "Design a compound tabs component", "Create a small compound Tabs, TabList, Tab, and TabPanel API for a profile workspace. Keep one selected tab in the parent Tabs context, expose selected state accessibly, and render only the selected panel without allowing two tabs to appear selected.", "Selecting Skills marks only its tab aria-selected=true and displays the Skills panel.", "An unknown selected value does not silently display multiple panels.", "const TabsContext = React.createContext(null);\nfunction Tabs({ value, onValueChange, children }) { return <TabsContext.Provider value={{ value, onValueChange }}>{children}</TabsContext.Provider>; }\nfunction Tab({ value, children }) { const tabs = React.useContext(TabsContext); return <button role='tab' aria-selected={tabs.value === value} onClick={() => tabs.onValueChange(value)}>{children}</button>; }\nfunction TabPanel({ value, children }) { const tabs = React.useContext(TabsContext); return tabs.value === value ? <section role='tabpanel'>{children}</section> : null; }"],
            ["Hard", "Prevent a component boundary from hiding failures", "A reusable DataPanel catches every child exception and renders an empty panel, making real defects look like no results. Redesign the boundary so loading, empty, and request-error states are explicit props while rendering errors remain observable to the application's error boundary.", "An API error is passed as an explicit error state; an unexpected render exception reaches the error boundary.", "An empty data array is not shown when isLoading or error is present.", "function DataPanel({ isLoading, error, data, children }) { if (isLoading) return <p role='status'>Loading…</p>; if (error) return <p role='alert'>{error}</p>; if (data.length === 0) return <p>No records yet.</p>; return children(data); }"],
        ]
    },
    Props: {
        hints: ["Treat props as read-only inputs and make required versus optional values explicit.", "Check controlled updates, callback contracts, and missing values from the parent's perspective."],
        items: [
            ["Easy", "Pass a real listing into JobCard", "Define JobCard props for title, company, and location and render the values supplied by the list parent. Do not include a hardcoded company or fallback listing in the reusable component.", "Two different input records produce their own distinct card text.", "Missing optional location uses 'Location not provided', while title remains required.", "function JobCard({ title, company, location = 'Location not provided' }) { return <article><h2>{title}</h2><p>{company}</p><span>{location}</span></article>; }"],
            ["Easy", "Use a callback prop for a details action", "Create a ViewDetails button that accepts onView and jobId props, passing the current ID to the callback on activation. The button must remain disabled when the callback is unavailable.", "Activating a button for job 'j-7' calls onView('j-7').", "A missing callback cannot cause a runtime error or claim that details opened.", "function ViewDetails({ jobId, onView }) { return <button type='button' disabled={!onView} onClick={() => onView?.(jobId)}>View details</button>; }"],
            ["Medium", "Control a child filter from its parent", "Build a RoleSelect that receives value, options, and onChange. Parent reset logic must update the displayed select immediately; do not copy the initial prop into independent child state.", "Changing the select notifies the parent and a parent reset returns it to Any Role.", "An option missing from the latest options list does not display an invented selection.", "function RoleSelect({ value, options, onChange }) { return <select value={options.includes(value) ? value : ''} onChange={(event) => onChange(event.target.value)}><option value=''>Any Role</option>{options.map((option) => <option key={option} value={option}>{option}</option>)}</select>; }"],
            ["Medium", "Pass stable row actions without mutating records", "A job list passes each row a save callback. Define JobCard so it calls onSave with job.id and never writes a saved flag onto the job prop; saved state remains owned by the list.", "Saving job j2 calls onSave('j2') and leaves the original record unchanged.", "A missing onSave callback leaves the view button usable and save action safely unavailable.", "function JobCard({ job, onSave }) { return <article><h2>{job.title}</h2><button type='button' disabled={!onSave} aria-label={`Save ${job.title}`} onClick={() => onSave?.(job.id)}>Save</button></article>; }"],
            ["Hard", "Define a render-prop contract for filtered results", "Design a ResultsProvider component that accepts items, predicate, and children render function. It should pass the derived visible list and total count to children, without owning API fetching or copying items into state.", "The render function receives the filtered records and their exact count.", "Changing predicate or items updates the derived result on the next render.", "function ResultsProvider({ items, predicate, children }) { const visible = React.useMemo(() => items.filter(predicate), [items, predicate]); return children({ items: visible, count: visible.length }); }"],
            ["Hard", "Distinguish controlled and uncontrolled input contracts", "A reusable SearchField currently accepts both defaultValue and value and becomes controlled inconsistently. Define one controlled contract requiring value and onChange, explain how the parent resets it, and preserve input accessibility.", "Parent value updates are reflected immediately and typing reports the new string.", "A reset from 'react' to '' clears the field without remounting it.", "function SearchField({ value, onChange, label = 'Search' }) { const id = React.useId(); return <label htmlFor={id}>{label}<input id={id} value={value} onChange={(event) => onChange(event.target.value)} /></label>; }"],
        ]
    },
    State: {
        hints: ["Store only values that cannot be derived; update them with setters so React schedules rendering.", "When next state depends on current state, use the functional updater and keep related transitions coherent."],
        items: [
            ["Easy", "Toggle an interview reminder", "Create a reminder button with local React state. It should show Set reminder or Reminder set and expose the current state through aria-pressed; do not alter its label through a DOM query.", "Initial false renders Set reminder and aria-pressed=false; one click changes both.", "Two clicks restore the initial state.", "function ReminderButton() { const [enabled, setEnabled] = React.useState(false); return <button type='button' aria-pressed={enabled} onClick={() => setEnabled((value) => !value)}>{enabled ? 'Reminder set' : 'Set reminder'}</button>; }"],
            ["Easy", "Keep a numeric input as text while editing", "Build a controlled score field that stores the text the user is typing and derives a valid numeric score only when the entire value is a finite number. Do not coerce an empty string into zero while the field is blank.", "Typing '08' keeps '08' visible and derives score 8.", "An empty input remains empty with no score; '8x' is invalid.", "function ScoreField() { const [text, setText] = React.useState(''); const score = text.trim() !== '' && Number.isFinite(Number(text)) ? Number(text) : null; return <><input value={text} onChange={(event) => setText(event.target.value)} /><output>{score ?? 'Enter a score'}</output></>; }"],
            ["Medium", "Increment from the latest state", "A progress button can receive three rapid increments before React renders. Use a functional state update so each successful increment builds on the latest pending value, and display the current total.", "Three queued increments increase the total by three.", "The implementation does not close over a stale count value.", "function ProgressCounter() { const [count, setCount] = React.useState(0); return <button onClick={() => setCount((current) => current + 1)}>Completed {count}</button>; }"],
            ["Medium", "Reset dependent form state atomically", "A career goal form stores selected role and role-specific skills. When the role changes, reset selected skills in the same event transition so skills from the previous role cannot remain selected.", "Changing Full Stack to Data Analyst clears the old role's skills.", "Selecting the same role can retain skills if the product contract says no role change occurred.", "function reducer(state, action) { if (action.type === 'roleChanged') return { role: action.role, skills: [] }; if (action.type === 'skillsChanged') return { ...state, skills: action.skills }; return state; }"],
            ["Hard", "Model async save states without false success", "Build a save control with idle, saving, saved, and error states. Disable repeat submission while saving, show saved only after the awaited request resolves, and restore an actionable retry state after rejection.", "A rejected request displays an error and never says Saved.", "A second click while pending does not create another request.", "function SaveProfile({ save }) { const [status, setStatus] = React.useState('idle'); const submit = async () => { if (status === 'saving') return; setStatus('saving'); try { await save(); setStatus('saved'); } catch { setStatus('error'); } }; return <><button disabled={status === 'saving'} onClick={submit}>{status === 'saving' ? 'Saving…' : status === 'saved' ? 'Saved' : 'Save profile'}</button>{status === 'error' && <p role='alert'>Could not save. Try again.</p>}</>; }"],
            ["Hard", "Use a reducer for a multi-step wizard", "Model a three-step profile wizard with step, values, and validation errors in one reducer. Define next, back, fieldChanged, and validationFailed actions; next must not advance while errors exist.", "A valid next action increments step, while validationFailed stores errors and keeps the same step.", "Back from step 1 stays at step 1; values survive navigation between steps.", "function wizardReducer(state, action) { switch (action.type) { case 'fieldChanged': { const errors = Object.fromEntries(Object.entries(state.errors).filter(([key]) => key !== action.name)); return { ...state, values: { ...state.values, [action.name]: action.value }, errors }; } case 'validationFailed': return { ...state, errors: action.errors }; case 'next': return Object.keys(state.errors).length ? state : { ...state, step: Math.min(3, state.step + 1) }; case 'back': return { ...state, step: Math.max(1, state.step - 1) }; default: return state; } }"],
        ]
    },
    Events: {
        hints: ["Prefer semantic form and button events so pointer and keyboard users share the same behavior.", "Stop propagation only for the nested action that owns it, and guard pending async operations."],
        items: [
            ["Easy", "Submit a controlled project form", "Implement a project form submit handler that prevents navigation, trims the project name, and calls onCreate only when the trimmed name is non-empty. Clear the field only after onCreate resolves successfully.", "A valid submit calls onCreate once and clears after success.", "Blank input does not call the API; rejected creation retains the user's text.", "function ProjectForm({ onCreate }) { const [name, setName] = React.useState(''); const submit = async (event) => { event.preventDefault(); const value = name.trim(); if (!value) return; await onCreate(value); setName(''); }; return <form onSubmit={submit}><label>Project name<input value={name} onChange={(event) => setName(event.target.value)} /></label><button type='submit'>Create project</button></form>; }"],
            ["Easy", "Keep a card action from opening its parent", "A clickable job card contains a Save button. Stop only the Save button's click from triggering the card's open-details handler; both controls must remain native keyboard-operable controls.", "Save activation calls onSave without calling onOpen.", "Activating the title link still opens details.", "function JobCard({ job, onOpen, onSave }) { return <article onClick={() => onOpen(job.id)}><h2>{job.title}</h2><button type='button' onClick={(event) => { event.stopPropagation(); onSave(job.id); }}>Save</button></article>; }"],
            ["Medium", "Guard duplicate submissions during a request", "An enrollment button can be clicked multiple times before the API responds. Add a pending guard that ensures at most one request is active and always resets after success or failure.", "Two clicks in the pending interval cause one request.", "A failed request clears pending and permits an intentional retry.", "function EnrollButton({ enroll }) { const [pending, setPending] = React.useState(false); const submit = async () => { if (pending) return; setPending(true); try { await enroll(); } finally { setPending(false); } }; return <button disabled={pending} onClick={submit}>{pending ? 'Enrolling…' : 'Enroll'}</button>; }"],
            ["Medium", "Handle Escape for a dialog without stale closures", "Implement a dialog component that listens for Escape only while open and calls onClose. Keep the effect dependencies correct when the callback changes, and remove the listener after close or unmount.", "Escape while open calls the current onClose callback once.", "Escape while closed does nothing and no listener remains after unmount.", "function useEscape(open, onClose) { React.useEffect(() => { if (!open) return; const handle = (event) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', handle); return () => window.removeEventListener('keydown', handle); }, [open, onClose]); }"],
            ["Hard", "Support nested keyboard actions predictably", "A menu row opens details on Enter, while a sibling button removes the item. Use semantic interactive elements so Enter on the details link navigates, Space/Enter on Remove invokes only removal, and the actions never trigger each other.", "Enter on the details link opens details and Enter on Remove calls onRemove once.", "The controls are siblings rather than nested interactive elements, so keyboard activation is unambiguous.", "function MenuRow({ item, onRemove }) { return <article><Link to={`/items/${encodeURIComponent(item.id)}`}>{item.name}</Link><button type='button' onClick={() => onRemove(item.id)}>Remove</button></article>; }"],
            ["Hard", "Coordinate optimistic state with rollback", "A React action marks a task complete optimistically while the API request runs. If the request fails, restore the prior completion state, show an error, and avoid rolling back a newer action for the same task.", "A successful request keeps the optimistic state.", "A failed old request does not revert a more recent successful toggle.", "function useTaskCompletion(save) { const [completed, setCompleted] = React.useState({}); const [error, setError] = React.useState(''); const toggle = async (id) => { const previous = completed[id] ?? false; const next = !previous; const token = Symbol(id); setCompleted((state) => ({ ...state, [id]: next, [`${id}:token`]: token })); setError(''); try { await save(id, next); } catch { setCompleted((state) => state[`${id}:token`] === token ? { ...state, [id]: previous } : state); setError('Could not update task.'); } }; return { completed, error, toggle }; }"],
        ]
    },
    Hooks: {
        hints: ["Hooks must run in the same order on every render; custom hooks compose stateful behavior without relying on selectors.", "Memoization and effects need complete, stable dependencies and explicit cleanup when they acquire resources."],
        items: [
            ["Easy", "Create an independent toggle hook", "Implement useToggle(initialValue) returning value, toggle, and setValue. Two components using it must have independent values, and it must not use module-level mutable state or DOM selectors.", "Each component toggles its own value.", "Calling the hook conditionally is not allowed; use it unconditionally in the component body.", "function useToggle(initialValue = false) { const [value, setValue] = React.useState(initialValue); const toggle = React.useCallback(() => setValue((current) => !current), []); return [value, toggle, setValue]; }"],
            ["Easy", "Share a derived completion percentage hook", "Write useCompletionPercent(done, total) that returns a rounded percentage from 0 to 100 and returns 0 for an empty total. It should be a pure derived value and not create redundant state.", "useCompletionPercent(3,4) returns 75.", "A negative done value clamps to 0; done greater than total clamps to 100.", "function useCompletionPercent(done, total) { return React.useMemo(() => { if (!Number.isFinite(total) || total <= 0) return 0; return Math.round(Math.min(100, Math.max(0, done / total * 100))); }, [done, total]); }"],
            ["Medium", "Memoize a filtered roadmap only when inputs change", "Implement a custom useVisibleTopics(topics, query) that returns topics whose names match a trimmed case-insensitive query. Use memoization with both required dependencies and leave the input array unchanged.", "Changing query or topics recalculates visible topics.", "A whitespace query returns all topics; a case difference does not hide a match.", "function useVisibleTopics(topics, query) { return React.useMemo(() => { const term = query.trim().toLowerCase(); return topics.filter((topic) => !term || topic.toLowerCase().includes(term)); }, [topics, query]); }"],
            ["Medium", "Avoid an effect that mirrors derived state", "A component stores filteredJobs in state and updates it from jobs and query in an effect, causing a stale render. Replace the effect and duplicate state with a derived value; explain when useMemo is actually useful.", "The result list and count update from current jobs and query in the same render.", "Updating jobs while query is unchanged still updates results.", "function useFilteredJobs(jobs, query) { const term = query.trim().toLowerCase(); return jobs.filter((job) => !term || job.title.toLowerCase().includes(term)); }"],
            ["Hard", "Build a reusable request-state hook", "Implement useRequest(load) with idle, loading, success, and error states, a retry function, and an unmount-safe request identity so stale requests cannot overwrite newer results. Keep errors generic in displayed state.", "Retry starts a new loading state and latest response wins.", "An older request resolving after retry cannot replace the latest result or error.", "function useRequest(load) { const [state, setState] = React.useState({ status: 'idle', data: null, error: '' }); const sequence = React.useRef(0); const run = React.useCallback(async () => { const id = ++sequence.current; setState((current) => ({ ...current, status: 'loading', error: '' })); try { const data = await load(); if (sequence.current === id) setState({ status: 'success', data, error: '' }); } catch { if (sequence.current === id) setState((current) => ({ ...current, status: 'error', error: 'Unable to load data' })); } }, [load]); React.useEffect(() => () => { sequence.current += 1; }, []); return { ...state, retry: run }; }"],
            ["Hard", "Keep an event subscription stable in a hook", "Implement useOnlineStatus using the browser online and offline events. Subscribe once per mounted component, update state from the event, and remove both listeners on unmount; do not add listeners during render.", "An online event updates the returned status to true.", "Unmounting removes listeners so later browser events do not call setters.", "function useOnlineStatus() { const [online, setOnline] = React.useState(navigator.onLine); React.useEffect(() => { const onOnline = () => setOnline(true); const onOffline = () => setOnline(false); window.addEventListener('online', onOnline); window.addEventListener('offline', onOffline); return () => { window.removeEventListener('online', onOnline); window.removeEventListener('offline', onOffline); }; }, []); return online; }"],
        ]
    },
    useEffect: {
        hints: ["An effect synchronizes React with an external system; pure calculations belong in render, not in an effect.", "List every reactive dependency and clean up subscriptions, timers, and obsolete requests."],
        items: [
            ["Easy", "Subscribe to a document title", "Use an effect to set document.title from a pageTitle prop and restore the previous title when the component unmounts. The effect should run again when pageTitle changes.", "Changing the prop updates the browser title.", "Unmounting restores the title that was present before the component mounted.", "function PageTitle({ pageTitle }) { React.useEffect(() => { const previous = document.title; document.title = pageTitle; return () => { document.title = previous; }; }, [pageTitle]); return null; }"],
            ["Easy", "Set up and remove one event listener", "A component tracks viewport width. Use an effect to register one resize listener after mount, update state with window.innerWidth, and remove the same listener on unmount.", "A resize updates the displayed width.", "Unmounting prevents future resize events from updating the removed component.", "function useViewportWidth() { const [width, setWidth] = React.useState(() => window.innerWidth); React.useEffect(() => { const update = () => setWidth(window.innerWidth); window.addEventListener('resize', update); return () => window.removeEventListener('resize', update); }, []); return width; }"],
            ["Medium", "Fix an effect dependency loop", "An effect fetches opportunities and depends on a new inline options object created every render. Refactor dependencies so the request runs when the actual filters change, not after each state update caused by the request.", "Changing role or location triggers a request; updating results does not trigger another identical request.", "A stable empty filter does not create an infinite request loop.", "function useOpportunities(role, location) { const [jobs, setJobs] = React.useState([]); React.useEffect(() => { let active = true; fetchJobs({ role, location }).then((data) => { if (active) setJobs(data); }); return () => { active = false; }; }, [role, location]); return jobs; }"],
            ["Medium", "Cancel a stale detail fetch", "A detail effect loads a selected project ID. When the ID changes or the component unmounts, cancel the previous fetch with AbortController so an old response cannot replace the newly selected record.", "Selecting project b after project a shows b even if a responds later.", "Unmounting aborts the active request and does not show a user-facing failure for that expected abort.", "function useProject(id) { const [project, setProject] = React.useState(null); React.useEffect(() => { const controller = new AbortController(); fetch(`/api/projects/${id}`, { signal: controller.signal }).then((response) => { if (!response.ok) throw new Error('Request failed'); return response.json(); }).then(setProject).catch((error) => { if (error.name !== 'AbortError') console.error('Project load failed'); }); return () => controller.abort(); }, [id]); return project; }"],
            ["Hard", "Avoid stale closure data in an interval", "A progress reminder interval logs a count but always reports the initial render's value. Refactor using either a complete effect dependency strategy or a functional state update, and ensure the interval is cleaned up.", "After count changes, interval behavior reflects the latest count.", "Only one interval remains active after repeated renders.", "function useReminder(count) { React.useEffect(() => { const timer = setInterval(() => console.log('Completed topics:', count), 5000); return () => clearInterval(timer); }, [count]); }"],
            ["Hard", "Combine independent effect requests with cancellation", "A dashboard effect loads profile and activity data independently. Start both requests concurrently, cancel both when userId changes, and commit neither result if the effect has been cleaned up; retain an explicit error state if either current request fails.", "Changing user ID cannot mix profile data from one account with activity from another.", "One request resolving after cancellation does not update state.", "function useDashboard(userId) { const [state, setState] = React.useState({ status: 'loading', profile: null, activity: [] }); React.useEffect(() => { const controller = new AbortController(); let active = true; const options = { signal: controller.signal }; Promise.all([fetchProfile(userId, options), fetchActivity(userId, options)]).then(([profile, activity]) => { if (active) setState({ status: 'success', profile, activity }); }).catch((error) => { if (active && error.name !== 'AbortError') setState({ status: 'error', profile: null, activity: [] }); }); return () => { active = false; controller.abort(); }; }, [userId]); return state; }"],
        ]
    },
    "Context API": {
        hints: ["Use Context for values shared across a subtree, not as a replacement for every local state variable.", "Memoize provider values when needed and make missing-provider behavior explicit."],
        items: [
            ["Easy", "Provide the active theme to a subtree", "Create ThemeContext and a provider that supplies the current light/dark value. A nested button should read the value with useContext and display the correct label without prop drilling through unrelated components.", "A dark provider produces a button labelled Switch to light theme.", "An unsupported theme uses a documented fallback rather than undefined text.", "const ThemeContext = React.createContext('light');\nfunction ThemeProvider({ theme, children }) { return <ThemeContext.Provider value={theme}>{children}</ThemeContext.Provider>; }\nfunction ThemeButton() { const theme = React.useContext(ThemeContext); return <button>Switch to {theme === 'dark' ? 'light' : 'dark'} theme</button>; }"],
            ["Easy", "Read a locale from context", "Build a LocaleContext with English default and a Greeting component that uses it to select English or Spanish greeting text. The default context must work when the component is rendered without a provider.", "No provider renders Hello; Spanish provider renders Hola.", "An unknown locale returns a neutral fallback and never crashes.", "const LocaleContext = React.createContext('en');\nfunction Greeting() { const locale = React.useContext(LocaleContext); const text = locale === 'es' ? 'Hola' : locale === 'en' ? 'Hello' : 'Welcome'; return <p>{text}</p>; }"],
            ["Medium", "Avoid recreating an expensive provider value", "A notification provider supplies count and markRead, but creates a new object and callback every render, causing all consumers to rerender. Use useCallback and useMemo with complete dependencies while keeping count updates correct.", "A consumer does not receive a changed context identity when unrelated provider state renders.", "Updating count changes the context value and all relevant consumers see the new count.", "function NotificationProvider({ children }) { const [count, setCount] = React.useState(0); const markRead = React.useCallback(() => setCount((value) => Math.max(0, value - 1)), []); const value = React.useMemo(() => ({ count, markRead }), [count, markRead]); return <NotificationContext.Provider value={value}>{children}</NotificationContext.Provider>; }"],
            ["Medium", "Share an authenticated user without prop chains", "Provide a user object through AuthContext so a deeply nested profile menu can display the current user's name. Keep an explicit loading or signed-out state and do not invent a default user.", "A loaded user displays their real name; loading and signed-out states remain distinct.", "Missing provider does not silently render a fabricated account.", "const AuthContext = React.createContext(null);\nfunction ProfileMenu() { const auth = React.useContext(AuthContext); if (!auth) throw new Error('ProfileMenu requires AuthProvider'); if (auth.status === 'loading') return <span role='status'>Loading account</span>; if (!auth.user) return <a href='/login'>Sign in</a>; return <span>{auth.user.name}</span>; }"],
            ["Hard", "Split high-frequency and low-frequency context", "A single context contains theme, current user, and rapidly changing editor text, forcing the entire application tree to rerender on each keystroke. Propose and implement separate contexts for theme and editor draft, keeping each provider close to its consumers.", "Typing changes editor consumers without changing theme context identity.", "Theme updates still propagate to theme consumers without coupling to editor drafts.", "const ThemeContext = React.createContext('dark');\nconst DraftContext = React.createContext('');\nfunction EditorProviders({ theme, draft, children }) { return <ThemeContext.Provider value={theme}><DraftContext.Provider value={draft}>{children}</DraftContext.Provider></ThemeContext.Provider>; }"],
            ["Hard", "Make a provider contract testable", "Create a UserSettingsContext with a provider that accepts initial settings and an update function. The consumer should show a safe unavailable state outside the provider rather than throwing or fabricating settings, and the provider must pass updates through unchanged.", "The consumer without a provider renders Settings unavailable.", "A provider update reaches the consumer with the exact provided settings object.", "const UserSettingsContext = React.createContext(null);\nfunction SettingsSummary() { const value = React.useContext(UserSettingsContext); return value ? <p>{value.settings.theme}</p> : <p>Settings unavailable</p>; }\nfunction UserSettingsProvider({ value, children }) { return <UserSettingsContext.Provider value={value}>{children}</UserSettingsContext.Provider>; }"],
        ]
    },
    "React Router": {
        hints: ["Route state belongs to the router; build internal destinations from known paths and preserve route parameters safely.", "Test direct URLs, missing records, and navigation without a full-page reload."],
        items: [
            ["Easy", "Link a job card to its detail route", "Create a job title link using React Router's Link to navigate to /jobs/:id for the selected record. Do not use window.location for internal navigation or hardcode a particular job ID.", "A card for j-8 links to /jobs/j-8 and keeps the SPA shell mounted.", "A record without an ID does not produce an '/undefined' route.", "function JobLink({ job }) { if (!job?.id) return <span>{job?.title ?? 'Job unavailable'}</span>; return <Link to={`/jobs/${encodeURIComponent(job.id)}`}>{job.title}</Link>; }"],
            ["Easy", "Read a route parameter", "Implement a job detail route component that reads the id parameter and passes it to a loader or request. Show a clear missing-ID state rather than requesting a literal undefined identifier.", "URL /jobs/j-8 passes j-8 to the data loader.", "A missing parameter does not issue a request.", "function JobDetailRoute() { const { id } = useParams(); if (!id) return <p>Job ID is missing.</p>; return <JobDetail id={id} />; }"],
            ["Medium", "Navigate after a successful create", "A project creation form should navigate to the new project detail route only after the API confirms creation. Use useNavigate and the returned record ID; on failure keep the form and display an error.", "A successful API response with id p-4 navigates to /projects/p-4.", "A failed request causes no navigation and does not display success.", "function CreateProject({ createProject }) { const navigate = useNavigate(); const submit = async (values) => { try { const project = await createProject(values); if (!project?.id) throw new Error('Missing project ID'); navigate(`/projects/${encodeURIComponent(project.id)}`); } catch { return { error: 'Project could not be created.' }; } }; return <ProjectForm onSubmit={submit} />; }"],
            ["Medium", "Protect a return path from external URLs", "After login, return a user to a requested internal route only when it begins with one slash and not two. Reject external, protocol-relative, and javascript destinations and fall back to /dashboard.", "'/projects?tab=active' is accepted.", "'//evil.test', 'https://evil.test', and 'javascript:alert(1)' fall back safely.", "function safeReturnTo(value) { return typeof value === 'string' && value.startsWith('/') && !value.startsWith('//') && !value.includes('\\\\') ? value : '/dashboard'; }"],
            ["Hard", "Preserve search state with router navigation", "A paginated jobs page stores keyword and page in the URL search parameters. Updating the keyword resets page to 1; changing page preserves the keyword. Use router navigation and avoid manually concatenating unescaped query strings.", "Changing keyword to 'C++' yields an encoded search param and page=1.", "Changing page to 2 retains the exact current keyword.", "function useJobSearchParams() { const [params, setParams] = useSearchParams(); const update = (change) => setParams((current) => { const next = new URLSearchParams(current); change(next); return next; }); const setKeyword = (keyword) => update((next) => { next.set('q', keyword); next.set('page', '1'); }); const setPage = (page) => update((next) => next.set('page', String(page))); return { keyword: params.get('q') ?? '', page: Number(params.get('page') || 1), setKeyword, setPage }; }"],
            ["Hard", "Handle nested routes and not-found states", "Design routes for /roadmap/:track/:phase with a shared roadmap layout, nested topic route, and explicit not-found handling for unknown tracks or phases. Do not let the detail component render an unrelated default phase when a URL segment is invalid.", "A valid nested URL renders the selected phase inside the shared layout.", "An unknown phase displays a not-found state and does not silently select phase one.", "<Route path='roadmap/:trackId' element={<RoadmapLayout />}><Route path=':phaseId' element={<RoadmapPhaseRoute />} /><Route path='*' element={<NotFound />} /></Route>\nfunction RoadmapPhaseRoute() { const { trackId, phaseId } = useParams(); const phase = findPhase(trackId, phaseId); return phase ? <PhaseDetails phase={phase} /> : <NotFound />; }"],
        ]
    },
    Forms: {
        hints: ["Choose one source of truth for each field and validate both shape and user intent.", "Keep accessible labels and errors connected to controls; preserve input on failed requests."],
        items: [
            ["Easy", "Build a controlled email field", "Create a controlled email input with a visible label, value and onChange props, and an accessible required indicator. Keep the input editable and do not maintain an unsynchronized copy in child state.", "Typing updates the parent value and that value is rendered by the input.", "Resetting the parent value to an empty string clears the field.", "function EmailField({ value, onChange }) { const id = React.useId(); return <label htmlFor={id}>Email <span aria-hidden='true'>*</span><input id={id} type='email' required value={value} onChange={(event) => onChange(event.target.value)} /></label>; }"],
            ["Easy", "Show an inline required-field error", "Build a project title input that displays an error only after submit is attempted and the trimmed value is blank. Connect the error to the input with aria-describedby and set aria-invalid accurately.", "Before submit there is no error; after blank submit the message is associated with the field.", "A whitespace-only title is invalid even though the raw string length is nonzero.", "function TitleField({ value, onChange, submitted }) { const id = React.useId(); const error = submitted && !value.trim() ? 'Enter a project title.' : ''; return <><label htmlFor={id}>Project title</label><input id={id} value={value} onChange={(event) => onChange(event.target.value)} aria-invalid={Boolean(error)} aria-describedby={error ? `${id}-error` : undefined} />{error && <p id={`${id}-error`}>{error}</p>}</>; }"],
            ["Medium", "Validate a repeatable skill list", "Implement a React skill editor that lets a user add a non-empty trimmed skill, rejects case-insensitive duplicates, and removes by stable skill ID. Keep all existing skills when a new one is added.", "Adding 'React' then ' react ' yields one entry.", "Removing one skill leaves every other existing skill unchanged.", "function SkillsEditor() { const [skills, setSkills] = React.useState([]); const add = (name) => { const clean = name.trim(); if (!clean || skills.some((skill) => skill.name.toLowerCase() === clean.toLowerCase())) return; setSkills((current) => [...current, { id: crypto.randomUUID(), name: clean }]); }; const remove = (id) => setSkills((current) => current.filter((skill) => skill.id !== id)); return <SkillList skills={skills} onAdd={add} onRemove={remove} />; }"],
            ["Medium", "Keep server validation errors on the right field", "A profile update API returns field errors for email and location. Map only recognized field names to inline errors, show a generic summary for unknown fields, and retain the user's entered values.", "An email error appears beside email and the form values remain unchanged.", "An unexpected server field is not discarded silently and is not rendered as raw HTML.", "function ProfileForm({ values, save }) { const [errors, setErrors] = React.useState({}); const submit = async () => { try { await save(values); setErrors({}); } catch (error) { const fields = error.fields || {}; setErrors({ email: fields.email, location: fields.location, summary: Object.keys(fields).some((key) => !['email', 'location'].includes(key)) ? 'Some fields need attention.' : error.message }); } }; return <ProfileFields values={values} errors={errors} onSubmit={submit} />; }"],
            ["Hard", "Prevent a stale async validation result", "A username field checks availability as the user types. Ensure only the most recent validation response can update the error state; older responses must not mark a currently available username as taken.", "The response for 'alex2' wins even if 'alex' responds later.", "Unmounting the form prevents the pending check from updating state.", "function useUsernameAvailability(username, check) { const [available, setAvailable] = React.useState(null); const sequence = React.useRef(0); React.useEffect(() => { const id = ++sequence.current; if (!username.trim()) { setAvailable(null); return; } check(username).then((result) => { if (sequence.current === id) setAvailable(result); }); return () => { sequence.current += 1; }; }, [username, check]); return available; }"],
            ["Hard", "Submit a multi-section form atomically", "A career profile includes contact details and education entries. Validate all sections before sending one payload, preserve all existing education entries, and display a per-section error summary if any validation fails. Do not send a partial update or clear fields on failure.", "Valid sections cause exactly one API request containing all education entries.", "If education is invalid, no request is made and contact input remains available for correction.", "async function submitProfile(values, validate, save) { const errors = validate(values); if (Object.keys(errors).length) return { ok: false, errors }; try { await save({ contact: values.contact, education: values.education }); return { ok: true }; } catch { return { ok: false, errors: { form: 'Profile could not be saved.' } }; } }"],
        ]
    },
    "API Integration": {
        hints: ["Keep API data flow in one request boundary and render loading, empty, error, and success states distinctly.", "Verify the response envelope and status before presenting data or success to the user."],
        items: [
            ["Easy", "Load real records into a list", "Implement a React component that calls an injected listProjects API when mounted and renders its returned data array. Show loading, an honest empty state, and a retryable error; do not add sample records when the response is empty.", "A real empty array shows the empty message; returned records render by stable ID.", "A rejected request displays an error rather than zero results.", "function ProjectsPanel({ listProjects }) { const [state, setState] = React.useState({ status: 'loading', data: [] }); const load = React.useCallback(async () => { setState((current) => ({ ...current, status: 'loading' })); try { const data = await listProjects(); setState({ status: data.length ? 'success' : 'empty', data }); } catch { setState((current) => ({ ...current, status: 'error' })); } }, [listProjects]); React.useEffect(() => { load(); }, [load]); if (state.status === 'loading') return <p role='status'>Loading projects…</p>; if (state.status === 'error') return <button onClick={load}>Retry</button>; if (state.status === 'empty') return <p>No projects yet.</p>; return state.data.map((project) => <article key={project.id}>{project.name}</article>); }"],
            ["Easy", "Check the response envelope before rendering", "A project service returns {success, data}. Build a loader that accepts only success=true with an array data field and otherwise throws a safe error for the component to display.", "A valid envelope returns the array.", "A 200 response with malformed or missing data does not render as an empty successful list.", "async function loadProjects(api) { const response = await api(); if (!response?.success || !Array.isArray(response.data)) throw new Error('Invalid project response'); return response.data; }"],
            ["Medium", "Keep filters when retrying a request", "A job page loads with role and location filters. Implement a retry handler that uses the current filter values through the same API helper, preserves the selected filters after failure, and updates results only on success.", "Retry repeats the same role/location query currently displayed.", "A second failure remains an error; old results are not mislabeled as the new filtered response.", "function useJobs(searchJobs, role, location) { const [state, setState] = React.useState({ status: 'idle', jobs: [], error: '' }); const load = React.useCallback(async () => { setState((current) => ({ ...current, status: 'loading', error: '' })); try { const jobs = await searchJobs({ role, location }); setState({ status: 'success', jobs, error: '' }); } catch { setState((current) => ({ ...current, status: 'error', error: 'Jobs could not be loaded.' })); } }, [searchJobs, role, location]); return { ...state, retry: load }; }"],
            ["Medium", "Avoid duplicate requests from effect dependencies", "A component creates a new API options object during each render and includes it in an effect dependency array, causing repeated requests. Move primitive query dependencies into the effect and preserve the shared service call.", "Changing page triggers one request; a request-state render does not trigger another.", "The component does not suppress a legitimate page change.", "function usePage(page, fetchPage) { const [data, setData] = React.useState([]); React.useEffect(() => { let active = true; fetchPage(page).then((result) => { if (active) setData(result); }); return () => { active = false; }; }, [page, fetchPage]); return data; }"],
            ["Hard", "Reconcile optimistic updates with API truth", "A favorite toggle updates the UI immediately and sends an authenticated API request. Roll back only the failed request's own optimistic update, preserve a newer toggle, and never show a saved confirmation before success is confirmed.", "Successful save leaves the item saved after server response.", "An older failed request cannot undo a later successful user action.", "function useFavorite(saveFavorite) { const [favorites, setFavorites] = React.useState({}); const versions = React.useRef({}); const toggle = async (id) => { const version = (versions.current[id] || 0) + 1; versions.current[id] = version; const before = Boolean(favorites[id]); const next = !before; setFavorites((current) => ({ ...current, [id]: next })); try { await saveFavorite(id, next); } catch { if (versions.current[id] === version) setFavorites((current) => ({ ...current, [id]: before })); } }; return { favorites, toggle }; }"],
            ["Hard", "Coordinate pagination with changing filters", "Build a jobs hook that resets page to 1 whenever role or location changes, requests the selected page and filters together, ignores stale responses, and preserves the current API response envelope. Do not fetch every page unnecessarily.", "Changing role while on page 4 requests page 1 for the new role.", "An old page response cannot replace results for the new filter.", "function useJobSearch(api, role, location) { const [page, setPage] = React.useState(1); const [state, setState] = React.useState({ data: [], pagination: null, status: 'loading' }); const requestId = React.useRef(0); React.useEffect(() => { setPage(1); }, [role, location]); React.useEffect(() => { const id = ++requestId.current; api({ role, location, page }).then((response) => { if (requestId.current === id) setState({ ...response, status: 'success' }); }).catch(() => { if (requestId.current === id) setState((current) => ({ ...current, status: 'error' })); }); }, [api, role, location, page]); return { ...state, page, setPage }; }"],
        ]
    },
    Authentication: {
        hints: ["The server remains authoritative for identity and permission; the UI only reflects its response.", "Do not put secrets in routes or state, and distinguish a 401 session issue from network failure."],
        items: [
            ["Easy", "Render a signed-out route state", "Create an AuthGate that shows a loading status while authentication is unresolved, renders children only for an authenticated user, and otherwise provides a sign-in link that preserves a safe internal return path.", "Authenticated state renders the protected content.", "Loading state does not briefly reveal protected content; external return URLs are rejected.", "function AuthGate({ status, user, children, returnTo }) { if (status === 'loading') return <p role='status'>Checking session…</p>; if (user) return children; const safe = typeof returnTo === 'string' && returnTo.startsWith('/') && !returnTo.startsWith('//') && !returnTo.includes('\\\\') ? returnTo : '/dashboard'; return <Link to={`/login?returnTo=${encodeURIComponent(safe)}`}>Sign in</Link>; }"],
            ["Easy", "Handle a 401 response honestly", "A protected API call receives 401. Display a session-expired message and offer sign-in; do not interpret a network failure as 401 and do not render the protected response.", "HTTP 401 triggers the expired-session state.", "A rejected fetch without an HTTP response shows a network error instead.", "async function loadPrivate(api) { try { return { status: 'success', data: await api() }; } catch (error) { if (error.status === 401) return { status: 'unauthenticated', message: 'Your session expired. Sign in again.' }; return { status: 'error', message: 'Could not connect. Try again.' }; } }"],
            ["Medium", "Protect an admin action at both layers", "An admin-only button is hidden from regular users, but a crafted request may still reach the API. Design the client response handling for 403 and explain that the backend must enforce the role independently.", "A 403 displays an access-denied message and no success state.", "Changing a role value in browser state does not grant server permission.", "async function runAdminAction(api) { try { await api(); return { status: 'success' }; } catch (error) { if (error.status === 403) return { status: 'error', message: 'You do not have permission to perform this action.' }; throw error; } }"],
            ["Medium", "Avoid storing credentials in component state", "A login form submits credentials through the existing authentication service. Keep the password only in the controlled field needed for submission, clear it after a definitive response, and never place it in a URL, notification, or persistent browser storage.", "The authentication service receives the submitted values and the password field clears after response.", "A network failure leaves the user able to retry without writing credentials to localStorage.", "async function submitLogin(values, login, clearPassword) { try { return await login(values); } finally { clearPassword(); } }"],
            ["Hard", "Handle token expiry without retry loops", "A shared API helper gets 401 from a protected request. Invalidate the current session and show the established sign-in flow, but do not repeatedly retry the same request with the expired token or log token contents.", "One 401 causes one session invalidation and no automatic replay loop.", "A 500 response does not clear authentication state.", "async function authenticatedRequest(request, auth) { try { return await request(auth.token); } catch (error) { if (error.status === 401) { auth.clearSession(); throw new Error('Session expired'); } throw error; } }"],
            ["Hard", "Keep account data isolated during account switching", "A dashboard request for user A is still pending when the app switches to user B. Ensure the previous request is cancelled or invalidated and only user B's authenticated response can populate the current UI.", "The rendered profile belongs to the currently authenticated account.", "A late response for A cannot overwrite B's profile after switching accounts.", "function useAccountProfile(userId, getProfile) { const [profile, setProfile] = React.useState(null); const sequence = React.useRef(0); React.useEffect(() => { const id = ++sequence.current; let active = true; getProfile(userId).then((value) => { if (active && sequence.current === id) setProfile(value); }); return () => { active = false; sequence.current += 1; }; }, [userId, getProfile]); return profile; }"],
        ]
    },
};

const slug = (value) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

export const REACT_MORE_EXERCISES = Object.fromEntries(Object.entries(reactScenarios).map(([topic, data]) => [
    topic,
    data.items.map(([difficulty, title, problem, expected, edgeCase, solutionCode], index) => ({
        id: `fs-react-${slug(topic)}-${difficulty.toLowerCase()}-${index + 2}-v1`,
        career: "Full Stack Developer",
        phase: "React.js",
        topic,
        title,
        difficulty,
        estimatedTime: difficulty === "Easy" ? "25–35 minutes" : difficulty === "Medium" ? "40–55 minutes" : "55–75 minutes",
        kind: "coding",
        language: "React / JavaScript",
        problemStatement: `${problem} Implement the behavior in a small React feature and explain how the expected result follows from React's state, props, event, or routing model. Verify both the representative case and the boundary case.`,
        simplerProblem: `First implement the normal case: ${expected}`,
        learningObjectives: [
            `Apply ${topic} to the concrete React feature described in this exercise.`,
            `Trace the data or event to its owner and explain the visible result.`,
            `Verify the edge case without fabricating data or hiding a failure.`
        ],
        requirements: [
            `Implement the ${topic}-specific behavior using the stated props, state, event, or route contract.`,
            `Keep the component keyboard-operable and expose state or errors accessibly when the interaction requires it.`,
            `Preserve the source data and show a distinct empty, error, or fallback state where the prompt calls for one.`
        ],
        examples: [
            { input: problem, output: expected, explanation: `This demonstrates the intended ${topic} behavior for the primary scenario.` },
            { input: `Boundary case: ${edgeCase}`, output: edgeCase, explanation: "This verifies the specified edge condition instead of testing only the happy path." }
        ],
        tests: [
            { name: "Primary scenario", input: problem, expected },
            { name: "Boundary scenario", input: edgeCase, expected: edgeCase }
        ],
        hints: data.hints,
        conceptsToReview: [topic, "Component state and props", "Accessible interaction"],
        prerequisites: ["JavaScript functions", "JSX", "Basic React rendering"],
        approach: `Define the React contract before coding: identify the input props or state, the event or external value that changes, and the result that should render. Implement the ${topic} behavior without mutating caller data or relying on direct DOM changes, then check the representative output and boundary condition.`,
        walkthrough: `Start with the initial component inputs and trace them through the interaction. For the primary case, the component should produce: ${expected} Then follow the edge case: ${edgeCase} The reference implementation makes the relevant state or event transition explicit so the behavior can be tested independently.`,
        solutionCode,
        solutionLines: [
            `Keep the ${topic} behavior in the correct React owner: props for supplied data, state for changing UI data, and effects only for external synchronization.`,
            `Implement the primary interaction with an explicit callback or state transition.`,
            `Verify the primary and boundary cases and preserve keyboard or error behavior requested by the prompt.`
        ],
        commonMistakes: [
            "Mutating props or reaching into the DOM instead of updating React-owned state.",
            "Testing only the successful path and hiding a failed request as an empty result.",
            "Using unstable list keys or omitting effect cleanup when the exercise involves repeated elements or subscriptions."
        ],
        followUp: `Extend ${title.toLowerCase()} with one additional realistic user interaction while preserving its current boundary behavior.`,
        completionCriteria: [
            `The primary scenario renders or behaves as expected: ${expected}`, 
            `The edge case is handled deliberately: ${edgeCase}`, 
            `The implementation uses the relevant ${topic} principle and does not introduce stale, fabricated, or inaccessible UI state.`
        ],
        starterCode: `function ${slug(title).replace(/-/g, "")}(props) {\n  // Implement the behavior described above.\n}`
    }))
]));
